def transform(grid):
    counts = {2: 0, 3: 0}
    for row in grid:
        for color in counts:
            in_run = False
            for value in row:
                if value == color and not in_run:
                    counts[color] += 1
                in_run = value == color

    vals = [3] * counts[3] + [2] * counts[2]
    vals = vals[:6]
    vals += [0] * (6 - len(vals))
    return [vals[:3], vals[3:]]
